// ===== Bibliothèque commune · Suivi de commande client (Growth Ex Machina × Qwokka) =====
// Dates en chaînes AAAA-MM-JJ (fuseau Europe/Paris), jours ouvrés France, jeton d'espace de suivi, échappement HTML.
const pad2 = n => String(n).padStart(2, '0');
const toStr = d => `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}`;
const parseDate = s => {
  if (s === null || s === undefined) return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s).trim());
  if (!m) return null;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return isNaN(d) ? null : d;
};
const parisToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris' }).format(new Date());
function easter(y) {
  const a = y % 19, b = Math.floor(y / 100), c = y % 100, d = Math.floor(b / 4), e = b % 4,
    f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30,
    i = Math.floor(c / 4), k = c % 4, l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451),
    month = Math.floor((h + l - 7 * m + 114) / 31), day = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(Date.UTC(y, month - 1, day));
}
function makeCalendar(fermetures) {
  const cache = {}; const extra = new Set(fermetures || []);
  const feries = y => { const e = easter(y); const p = n => { const d = new Date(e); d.setUTCDate(d.getUTCDate() + n); return toStr(d); };
    return new Set([`${y}-01-01`, p(1), `${y}-05-01`, `${y}-05-08`, p(39), p(50), `${y}-07-14`, `${y}-08-15`, `${y}-11-01`, `${y}-11-11`, `${y}-12-25`]); };
  const isBD = d => { const w = d.getUTCDay(); if (w === 0 || w === 6) return false; const y = d.getUTCFullYear(); if (!cache[y]) cache[y] = feries(y); return !cache[y].has(toStr(d)) && !extra.has(toStr(d)); };
  const addBD = (d, n) => { const x = new Date(d); const s = n >= 0 ? 1 : -1; let k = Math.abs(n); while (k > 0) { x.setUTCDate(x.getUTCDate() + s); if (isBD(x)) k--; } return x; };
  const diffBD = (a, b) => { if (toStr(a) === toStr(b)) return 0; const s = b > a ? 1 : -1; const x = new Date(a); let c = 0, guard = 0; while (toStr(x) !== toStr(b) && guard++ < 4000) { x.setUTCDate(x.getUTCDate() + s); if (isBD(x)) c += s; } return c; };
  const addDays = (d, n) => { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x; };
  return { isBD, addBD, diffBD, addDays };
}
const JOURS = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
const MOIS = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];
const frDate = d => `${JOURS[d.getUTCDay()]} ${d.getUTCDate() === 1 ? '1er' : d.getUTCDate()} ${MOIS[d.getUTCMonth()]}`;
const frDateY = d => `${frDate(d)} ${d.getUTCFullYear()}`;
const frShort = d => `${pad2(d.getUTCDate())}/${pad2(d.getUTCMonth() + 1)}`;
const esc = s => String(s === null || s === undefined ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// Jeton de l'espace de suivi : empreinte de l'email + secret. Démo uniquement ; en production, lien signé ou lien de connexion.
function jeton(email, secret) {
  const str = String(email || '').trim().toLowerCase() + '|' + secret;
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) { const ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36) + (h1 >>> 0).toString(36);
}
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;
const STATUTS = ['Commande_confirmee', 'En_preparation', 'Expediee', 'Livree'];
const parseSent = s => { try { const v = JSON.parse(s || '[]'); return Array.isArray(v) ? v : []; } catch (e) { return []; } };
// ===== Moteur de règles · passage quotidien =====
// Entrées : cfg (réglages), cmds (commandes ERP), memRows (mémoire du flux). Sortie : décisions par commande + messages.
function moteur(cfg, cmds, memRows) {
  const cal = makeCalendar(cfg.fermetures);
  const T = parseDate(cfg.date_reference);
  const mem = new Map(memRows.filter(r => r && r.order_number).map(r => [r.order_number, r]));
  const premierPassage = mem.size === 0;
  const lien = email => `${cfg.url_espace_suivi}?c=${jeton(email, cfg.secret_lien)}`;
  const decisions = [];

  for (const o of cmds) {
    if (!o || !o.order_number) continue;
    const m = mem.get(o.order_number) || null;
    const D = parseDate(o.delivery_date);
    const sent = m ? parseSent(m.sent) : [];
    const has = k => sent.includes(k);
    const r = { order_number: o.order_number, company: o.company, contact_email: o.contact_email, status: o.status,
      delivery_date: o.delivery_date || '', client: null, client_bloque: null, alertes: [], affichage: '', pourquoi: [], memoire: null };
    const alerte = (type, detail) => r.alertes.push({ type, detail });
    const emailOk = EMAIL_RE.test(o.contact_email || '');

    // Données inexploitables : rien côté client, alerte à l'équipe
    if (!STATUTS.includes(o.status)) { alerte('STATUT_INCONNU', `Statut « ${o.status} » hors des 4 statuts de l’API : aucune notification client`); r.pourquoi.push('Statut inconnu : le flux s’abstient.'); decisions.push(r); continue; }
    if (!D) { alerte('DATE_MANQUANTE', 'Date de livraison annoncée absente'); r.pourquoi.push('Pas de date : aucun calcul possible.'); decisions.push(r); continue; }

    const L = cal.addBD(D, -(cfg.prepa_jo + cfg.transport_jo));            // date limite d'arrivée des pièces (D − 3)
    const seuilRisque = cal.addBD(D, -cfg.alerte_risque_jo);               // début de l'alerte « risque de retard »
    const nouveau = !m;                                                     // première observation de la commande
    const statutChange = !m || m.last_status !== o.status;
    const statusSince = statutChange ? T : (parseDate(m.status_since) || T);
    let nbGliss = m ? Number(m.nb_glissements || 0) : 0;
    const initiale = m && m.initial_delivery_date ? m.initial_delivery_date : o.delivery_date;
    let msg = null;
    let situation = null;                                                   // retard déjà constaté à la découverte d'une commande

    // 1. Changement de date saisi par le distributeur (détecté grâce à la mémoire)
    const ancienne = m ? parseDate(m.last_delivery_date) : null;
    if (ancienne && toStr(ancienne) !== toStr(D) && o.status !== 'Livree') {
      const gl = cal.diffBD(ancienne, D);
      if (gl > 0) {
        nbGliss += 1;
        if (nbGliss >= 2) { msg = { type: 'RETARD_REPETE', palier: gl >= cfg.palier2_jo ? 2 : 1, glissement: gl, rang: nbGliss, ancienne: toStr(ancienne) }; alerte('RETARD_REPETE', `${nbGliss}e report de date (+${gl} j.o.) : démarche personnalisée à envisager`); }
        else msg = { type: 'NOUVELLE_DATE', palier: gl >= cfg.palier2_jo ? 2 : 1, glissement: gl, ancienne: toStr(ancienne) };
        r.pourquoi.push(`Nouvelle date saisie : ${frShort(ancienne)} → ${frShort(D)} (+${gl} j.o., palier ${msg.palier}).`);
      } else r.pourquoi.push(`Date avancée (${frShort(ancienne)} → ${frShort(D)}) : espace de suivi mis à jour, pas d’email.`);
    }

    switch (o.status) {
      case 'Commande_confirmee':
        if (T > L) {                                   // D − 2 ou après : retard certain
          r.affichage = 'Livraison retardée';
          if (!msg) {
            if ((nouveau && premierPassage) || has(`REPRISE|${o.delivery_date}`)) { if (nouveau) r.marqueur = `REPRISE|${o.delivery_date}`; alerte('RETARD_EXISTANT', `Déjà en retard à la mise en service (pièces attendues avant le ${frShort(L)}) : client à prévenir par l’équipe`); r.pourquoi.push('Déjà en retard à la mise en service du flux : pas de message client, l’équipe décide.'); }
            else {
              alerte('PROBLEME_NON_RESOLU', `Pièces attendues avant le ${frShort(L)}, aucune nouvelle date saisie`);
              if (nouveau) { situation = { retard: 'appro', cle: `RETARD_EN_COURS|${o.delivery_date}` }; r.pourquoi.push(`Découverte déjà en retard (date limite ${frShort(L)} dépassée) : l’email de suivi annonce le retard.`); }
              else if (!has(`RETARD_EN_COURS|${o.delivery_date}`)) { msg = { type: 'RETARD_EN_COURS' }; r.pourquoi.push(`Retard certain (date limite ${frShort(L)} dépassée), rien n’a été saisi : filet de sécurité.`); }
              else r.pourquoi.push('Client déjà prévenu de ce retard : alerte interne quotidienne seulement.');
            }
          }
        } else if (T >= seuilRisque) {                 // D − 3 (réglable) : risque de retard, interne seulement
          alerte('RISQUE_RETARD', `Pièces à recevoir au plus tard le ${frShort(L)} pour tenir le ${frShort(D)}`);
          r.affichage = 'En attente des articles fournisseurs';
          r.pourquoi.push('Dernier jour pour tenir la date : l’équipe est alertée, pas le client.');
        } else { r.affichage = 'En attente des articles fournisseurs'; if (!msg) r.pourquoi.push(`Dans les temps (date limite ${frShort(L)}).`); }
        break;
      case 'En_preparation': {
        const jours = cal.diffBD(statusSince, T);
        r.affichage = 'En préparation dans nos entrepôts';
        if (jours > cfg.prepa_jo) alerte('PREPA_DEPASSEE', `En préparation depuis ${jours} j.o. (standard : ${cfg.prepa_jo})`);
        if (toStr(T) >= toStr(D)) {
          r.affichage = 'Risque de retard de livraison';
          alerte('DATE_COMPROMISE', `Jour de livraison annoncé et commande pas encore expédiée`);
          if (nouveau) situation = { retard: 'prepa', cle: `RISQUE_RETARD_PREPA|${o.delivery_date}` };
          else if (!msg && !has(`RISQUE_RETARD_PREPA|${o.delivery_date}`)) { msg = { type: 'RISQUE_RETARD_PREPA' }; r.pourquoi.push('Jour D, toujours en préparation : message prudent au client.'); }
        } else if (!msg) r.pourquoi.push(jours > cfg.prepa_jo ? 'Préparation plus longue que prévu : alerte interne.' : 'Préparation normale : rien à envoyer.');
        break;
      }
      case 'Expediee': {
        const apres = cal.diffBD(D, T);
        r.affichage = 'Expédiée · livraison prévue le ' + frDate(D);
        if (apres >= 1) { alerte('LIVRAISON_NON_CONFIRMEE', `Expédiée, date annoncée dépassée de ${apres} j.o. : vérifier le transporteur`); r.affichage = 'Expédiée · livraison en cours de vérification'; }
        if (apres >= 2 && nouveau) situation = { retard: 'transport', cle: `LIVRAISON_RETARDEE|${o.delivery_date}` };
        else if (apres >= 2 && !msg && !has(`LIVRAISON_RETARDEE|${o.delivery_date}`)) { msg = { type: 'LIVRAISON_RETARDEE' }; r.pourquoi.push('D + 2 sans livraison confirmée : message au client.'); }
        else if (!msg) r.pourquoi.push(apres >= 1 ? 'Livraison non confirmée : alerte interne.' : 'Expédiée : pas d’email, l’espace de suivi suffit.');
        break;
      }
      case 'Livree': {
        r.affichage = 'Livrée';
        const enRetard = nbGliss > 0 || sent.some(k => /^(RETARD_EN_COURS|RISQUE_RETARD_PREPA|LIVRAISON_RETARDEE|NOUVELLE_DATE|RETARD_REPETE)\|/.test(k));
        if (!nouveau && statutChange && !has('LIVREE')) { msg = { type: enRetard ? 'LIVREE_RETARD' : 'LIVREE' }; r.pourquoi.push(enRetard ? 'Livrée après un retard : confirmation avec excuses.' : 'Livrée : confirmation et lien vers le support.'); }
        else r.pourquoi.push(nouveau ? 'Déjà livrée à la première observation : rien.' : 'Livraison déjà confirmée au client.');
        break;
      }
    }

    // Nouvelle commande (hors mise en service, hors déjà livrée) : un seul email, celui de suivi avec le lien vers l'espace.
    // S'il y a déjà un retard à la découverte, l'email de suivi l'annonce : pas de second email le même jour.
    if (nouveau && !premierPassage && o.status !== 'Livree') {
      msg = { type: 'SUIVI_COMMANDE', retard: situation ? situation.retard : null, cles_extra: situation ? [situation.cle] : [] };
      r.pourquoi.push(situation ? 'Nouvelle commande, déjà en retard : email de suivi avec l’information de retard.' : 'Nouvelle commande : email de suivi avec le lien vers l’espace de suivi.');
    }
    // Mise en service : au tout premier passage, aucune notification client
    if (msg && premierPassage) { r.pourquoi.push('Premier passage du flux : notification client retenue, l’équipe traite d’abord.'); msg = null; }
    if (msg) {
      msg.cle = msg.type === 'LIVREE' || msg.type === 'LIVREE_RETARD' ? 'LIVREE' : msg.type === 'SUIVI_COMMANDE' ? 'SUIVI' : `${msg.type}|${o.delivery_date}`;
      if (!emailOk) { r.client_bloque = { ...msg, raison: 'email invalide' }; alerte('EMAIL_INVALIDE', `« ${o.contact_email || ''} » : le message ${msg.type} n’a pas pu partir`); }
      else r.client = { ...msg, ...rendreEmailClient(msg, o, D, cfg, lien(o.contact_email), cal) };
    }
    const sentApres = [...sent, ...(r.client ? [r.client.cle, ...(r.client.cles_extra || [])] : []), ...(r.marqueur ? [r.marqueur] : [])];
    r.memoire = { order_number: o.order_number, contact_email: o.contact_email || '', last_status: o.status, status_since: toStr(statusSince),
      last_delivery_date: o.delivery_date, initial_delivery_date: initiale, nb_glissements: nbGliss, sent: JSON.stringify(sentApres), last_seen: toStr(T) };
    r.lien_espace = lien(o.contact_email);
    decisions.push(r);
  }
  return { decisions, premierPassage, digest: rendreDigest(decisions, cfg) };
}

// ===== Modèles d'emails clients =====
function rendreEmailClient(m, o, D, cfg, lienEspace, cal) {
  const n = o.order_number, B = cfg.marque;
  let sujet, paras = [], encadre = [];
  switch (m.type) {
    case 'SUIVI_COMMANDE': {
      const etat = { appro: 'Livraison retardée, nouvelle date en cours de confirmation', prepa: 'En préparation, risque de retard', transport: 'Expédiée, livraison non confirmée' }[m.retard]
        || { Commande_confirmee: 'Confirmée', En_preparation: 'En préparation', Expediee: 'Expédiée' }[o.status] || '';
      sujet = m.retard ? `Commande ${n} : suivi de votre commande et information de livraison` : `Commande ${n} : suivez votre commande en ligne`;
      paras = [`Merci pour votre commande n° ${n}. Vous pouvez suivre son avancement à tout moment depuis votre espace de suivi : préparation, expédition et livraison.`];
      if (m.retard === 'appro') paras.push(`Certains articles ne nous sont pas encore parvenus de nos fournisseurs : nous ne pourrons pas vous livrer à la date prévue du ${frDateY(D)}. Nous vous communiquerons votre nouvelle date de livraison dès qu’elle sera confirmée.`);
      else if (m.retard === 'prepa') paras.push(`Votre commande est en cours de préparation dans nos entrepôts et sa livraison, prévue le ${frDateY(D)}, risque d’être retardée. Nous traitons actuellement le sujet.`);
      else if (m.retard === 'transport') paras.push(`Votre commande a été remise à notre transporteur, mais sa livraison ne nous a pas encore été confirmée. Si vous ne l’avez pas reçue, nous vérifions immédiatement auprès du transporteur.`);
      else paras.push(`Livraison prévue le <b>${frDateY(D)}</b>. Vous serez prévenu par email si cette date devait changer.`);
      paras.push(`Pour toute question, notre service client est à votre disposition : il vous suffit de répondre à cet email.`);
      encadre = [['Commande', n], ['Livraison prévue', frDateY(D)], ['Statut', etat]];
      break;
    }
    case 'RETARD_EN_COURS':
      sujet = `Commande ${n} : votre livraison du ${frShort(D)} sera retardée`;
      paras = [`Certains articles de votre commande n° ${n} ne nous sont pas encore parvenus de nos fournisseurs. Nous ne pourrons pas vous livrer à la date prévue du ${frDateY(D)}.`,
        `Notre équipe met tout en œuvre pour résoudre la situation. Nous vous communiquerons votre nouvelle date de livraison dès qu’elle sera confirmée.`,
        `Pour toute question, notre service client est à votre disposition : il vous suffit de répondre à cet email.`];
      encadre = [['Commande', n], ['Livraison initialement prévue', frDateY(D)], ['Statut', 'Nouvelle date en cours de confirmation']];
      break;
    case 'NOUVELLE_DATE':
      sujet = `Commande ${n} : nouvelle date de livraison, ${frDate(D)}`;
      paras = [`Votre commande n° ${n} ne pourra pas être livrée à la date annoncée du ${frDateY(parseDate(m.ancienne))}. Nous vous prions de nous excuser pour ce contretemps.`,
        `Votre nouvelle date de livraison est le <b>${frDateY(D)}</b>.`];
      if (m.palier === 2) paras.push(`Nous mesurons la gêne que représente un tel décalage. Notre service client se tient à votre disposition pour en parler : répondez simplement à cet email.`);
      encadre = [['Commande', n], ['Nouvelle date de livraison', frDateY(D)]];
      break;
    case 'RETARD_REPETE':
      sujet = `Commande ${n} : nouveau report de livraison, ${frDate(D)}`;
      paras = [`Nous sommes sincèrement désolés : la livraison de votre commande n° ${n} doit à nouveau être décalée.`,
        `Votre nouvelle date de livraison est le <b>${frDateY(D)}</b>.`,
        `Notre service client va revenir vers vous personnellement. Vous pouvez aussi répondre directement à cet email.`];
      encadre = [['Commande', n], ['Nouvelle date de livraison', frDateY(D)], ['Report', `${m.rang}e report`]];
      break;
    case 'RISQUE_RETARD_PREPA':
      sujet = `Commande ${n} : risque de retard de livraison`;
      paras = [`Votre commande n° ${n}, prévue pour aujourd’hui, est encore en cours de préparation dans nos entrepôts. Sa livraison risque d’être retardée.`,
        `Nous traitons actuellement le sujet. Vous pouvez vous rapprocher de notre service client pour plus d’informations, en répondant à cet email.`];
      encadre = [['Commande', n], ['Livraison prévue', frDateY(D)], ['Statut', 'En préparation']];
      break;
    case 'LIVRAISON_RETARDEE':
      sujet = `Commande ${n} : votre livraison semble retardée`;
      paras = [`Votre commande n° ${n} a été remise à notre transporteur, mais sa livraison ne nous a pas encore été confirmée.`,
        `Si vous ne l’avez pas reçue, contactez notre service client en répondant à cet email : nous vérifions immédiatement auprès du transporteur.`];
      encadre = [['Commande', n], ['Livraison prévue', frDateY(D)], ['Statut', 'Expédiée, livraison non confirmée']];
      break;
    case 'LIVREE':
      sujet = `Commande ${n} livrée`;
      paras = [`Votre commande n° ${n} a bien été livrée. Merci pour votre confiance.`,
        `Si vous n’avez pas reçu votre commande ou si un article manque, contactez notre service client en répondant à cet email.`];
      encadre = [['Commande', n], ['Statut', 'Livrée']];
      break;
    case 'LIVREE_RETARD':
      sujet = `Commande ${n} livrée, avec nos excuses`;
      paras = [`Votre commande n° ${n} a bien été livrée. Nous vous renouvelons nos excuses pour le retard rencontré.`,
        `Si vous n’avez pas reçu votre commande ou si un article manque, contactez notre service client en répondant à cet email.`];
      encadre = [['Commande', n], ['Statut', 'Livrée']];
      break;
  }
  const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#15171C;max-width:560px;margin:0 auto">`
    + `<p style="font-size:13px;letter-spacing:2px;text-transform:uppercase;color:#C2360F;margin:0 0 18px">${esc(B)} · Suivi de commande</p>`
    + `<p>Bonjour,</p>${paras.map(p => `<p>${p}</p>`).join('')}`
    + `<table style="border-collapse:collapse;width:100%;margin:20px 0;background:#F7F5F0;border-radius:8px">${encadre.map(([k, v]) => `<tr><td style="padding:9px 14px;color:#5F6470;font-size:13px">${esc(k)}</td><td style="padding:9px 14px;font-weight:bold">${esc(v)}</td></tr>`).join('')}</table>`
    + `<p style="margin:24px 0"><a href="${lienEspace}" style="background:#15171C;color:#F7F5F0;text-decoration:none;padding:12px 20px;border-radius:999px;font-weight:bold">Suivre mes commandes</a></p>`
    + `<p>Bien cordialement,<br>L’équipe service client ${esc(B)}</p></div>`;
  return { sujet, html };
}

// ===== Récapitulatif interne quotidien =====
const LIBELLES = {
  PROBLEME_NON_RESOLU: ['Retard sans nouvelle date · client notifié', 1], RETARD_EXISTANT: ['Déjà en retard à la mise en service', 1],
  DATE_COMPROMISE: ['Date compromise en préparation', 1], RETARD_REPETE: ['Reports de date répétés', 2],
  RISQUE_RETARD: ['Risque de retard', 2], PREPA_DEPASSEE: ['Délai de préparation dépassé', 3],
  LIVRAISON_NON_CONFIRMEE: ['Livraison non confirmée', 3], EMAIL_INVALIDE: ['Email non délivrable', 4],
  STATUT_INCONNU: ['Statut inconnu', 4], DATE_MANQUANTE: ['Date de livraison manquante', 4],
};
function rendreDigest(decisions, cfg) {
  const T = parseDate(cfg.date_reference);
  const lignes = decisions.flatMap(r => r.alertes.map(a => ({ ...a, r })));
  const types = Object.keys(LIBELLES).filter(t => lignes.some(l => l.type === t)).sort((a, b) => LIBELLES[a][1] - LIBELLES[b][1]);
  const envoyes = decisions.filter(r => r.client);
  const sujet = `[Suivi commandes] ${frDate(T)} · ${lignes.length} alerte${lignes.length > 1 ? 's' : ''}, ${envoyes.length} email${envoyes.length > 1 ? 's' : ''} client`;
  let html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#15171C;max-width:780px">`
    + `<p style="font-size:13px;letter-spacing:2px;text-transform:uppercase;color:#C2360F">${esc(cfg.marque)} · Récapitulatif du ${frDateY(T)}</p>`
    + `<p>Bonjour l’équipe,</p><p>${lignes.length ? `${lignes.length} point(s) demandent votre attention ce matin. Les décisions restent les vôtres ; une fois l’ERP mis à jour, le client est prévenu automatiquement.` : 'Rien à signaler ce matin.'}</p>`;
  for (const t of types) {
    const ls = lignes.filter(l => l.type === t);
    html += `<h3 style="font-size:15px;margin:22px 0 6px">${esc(LIBELLES[t][0])} (${ls.length})</h3><table style="border-collapse:collapse;width:100%;font-size:13px">`
      + `<tr style="text-align:left;color:#5F6470"><th style="padding:4px 8px">Commande</th><th style="padding:4px 8px">Client</th><th style="padding:4px 8px">Annoncée</th><th style="padding:4px 8px">Détail</th><th style="padding:4px 8px">Client prévenu</th></tr>`
      + ls.map(l => `<tr style="border-top:1px solid #DCD8CF"><td style="padding:6px 8px;font-family:monospace">${esc(l.r.order_number)}</td><td style="padding:6px 8px">${esc(l.r.company)}</td><td style="padding:6px 8px">${l.r.delivery_date ? frShort(parseDate(l.r.delivery_date)) : '–'}</td><td style="padding:6px 8px">${esc(l.detail)}</td><td style="padding:6px 8px">${l.r.client ? 'oui, ce matin' : (l.r.memoire && parseSent(l.r.memoire.sent).some(k => k !== 'SUIVI' && !k.startsWith('REPRISE|')) ? 'oui, déjà' : 'non')}</td></tr>`).join('') + `</table>`;
  }
  if (envoyes.length) html += `<h3 style="font-size:15px;margin:22px 0 6px">Emails clients envoyés ce matin (${envoyes.length})</h3><ul>${envoyes.map(r => `<li>${esc(r.order_number)} · ${esc(r.company)} · ${esc(r.client.sujet)}</li>`).join('')}</ul>`;
  html += `</div>`;
  return { sujet, html, nb_alertes: lignes.length };
}
