const ETAPES = [['Commande_confirmee', 'Confirmée'], ['En_preparation', 'En préparation'], ['Expediee', 'Expédiée'], ['Livree', 'Livrée']];

function pageEspaceSuivi(cfg, cmds, memRows, token) {
  const calc = moteur(cfg, cmds, memRows).decisions;
  const mem = new Map(memRows.filter(r => r && r.order_number).map(r => [r.order_number, r]));
  const mine = calc.filter(r => r.contact_email && jeton(r.contact_email, cfg.secret_lien) === token && ETAPES.some(e => e[0] === r.status));
  const head = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Suivi de mes commandes · ${esc(cfg.marque)}</title>`
    + `<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Sora:wght@400;600;800&family=JetBrains+Mono:wght@500&display=swap"><style>${PAGE_CSS}</style></head><body><div class="wrap">`;
  if (!token || !mine.length) return head + `<p class="eyebrow">${esc(cfg.marque)} · Suivi de commande</p><h1>Lien invalide ou expiré</h1><p class="muted">Utilisez le bouton « Suivre mes commandes » de votre dernier email, ou répondez-y pour contacter notre service client.</p></div></body></html>`;
  const order = s => ETAPES.findIndex(e => e[0] === s);
  const cartes = mine.sort((a, b) => order(a.status) - order(b.status) || (a.delivery_date || '').localeCompare(b.delivery_date || '')).map(r => {
    const cur = order(r.status), m = mem.get(r.order_number), D = parseDate(r.delivery_date);
    const init = m && m.initial_delivery_date && m.initial_delivery_date !== r.delivery_date ? parseDate(m.initial_delivery_date) : null;
    const alerte = /retard|risque|vérification/i.test(r.affichage);
    const etat = r.status === 'Livree' ? 'ok' : alerte ? 'alerte' : '';
    const dateTxt = r.status === 'Livree' ? 'Livrée' : alerte && r.status === 'Commande_confirmee' ? 'Nouvelle date en cours de confirmation' : (D ? frDateY(D) : '–');
    return `<section class="card"><div class="top"><span class="co">${esc(r.company)}</span><span class="num">${esc(r.order_number)}</span></div>`
      + `<div class="steps">${ETAPES.map((e, i) => `<div class="step ${i < cur ? 'done' : i === cur ? 'cur' : ''}"><span class="bar"></span>${e[1]}</div>`).join('')}</div>`
      + (r.affichage && r.affichage !== 'En attente des articles fournisseurs' ? `<span class="etat ${etat}">${esc(r.affichage)}</span>` : '')
      + `<div class="meta"><span>Livraison : <b>${esc(dateTxt)}</b></span>${init ? `<span>Initialement prévue le ${esc(frDate(init))}</span>` : ''}</div></section>`;
  }).join('');
  return head + `<p class="eyebrow">${esc(cfg.marque)} · Suivi de commande</p><h1>Vos commandes en cours</h1><p class="muted">${esc(mine[0].contact_email)} · mis à jour chaque matin à 7h</p>${cartes}`
    + `<p class="foot muted">Une question ? Répondez à l’un de nos emails : votre message arrive directement à notre service client.</p></div></body></html>`;
}

function pageApercu(cfg, res, cmds) {
  const T = parseDate(cfg.date_reference);
  const ATT = new Map(cmds.map(c => [c.order_number, c]));
  const nbClient = res.decisions.filter(r => r.client).length;
  const lignes = res.decisions.map(r => {
    const c = ATT.get(r.order_number) || {};
    return `<tr><td class="num">${esc(r.order_number)}<div class="muted">${esc(r.company)}</div></td><td>${esc(r.status)}</td><td>${r.delivery_date ? frShort(parseDate(r.delivery_date)) : '–'}</td>`
      + `<td>${r.client ? `<b>${esc(r.client.type)}</b>` : r.client_bloque ? `<span class="ko">bloqué : ${esc(r.client_bloque.raison)}</span>` : '<span class="muted">–</span>'}</td>`
      + `<td>${r.alertes.map(a => `<span class="pill">${esc(a.type)}</span>`).join(' ') || '<span class="muted">–</span>'}</td>`
      + `<td class="muted">${esc(r.pourquoi.join(' '))}${c.scenario ? `<div class="scen">Scénario : ${esc(c.scenario)}</div>` : ''}</td></tr>`;
  }).join('');
  const emails = res.decisions.filter(r => r.client).map(r => `<article class="mail"><div class="mh"><span class="muted">À</span> ${esc(r.contact_email)}<br><span class="muted">Objet</span> <b>${esc(r.client.sujet)}</b></div><div class="mb">${r.client.html}</div></article>`).join('');
  const css = PAGE_CSS + `.wrap{max-width:1200px}table{width:100%;border-collapse:collapse;font-size:14px;background:#FFFDF8}th{text-align:left;font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:#5F6470;padding:10px;border-bottom:1px solid #DCD8CF}td{padding:10px;border-top:1px solid #DCD8CF;vertical-align:top}.box{overflow-x:auto;border:1px solid #DCD8CF;border-radius:14px;margin-top:16px}.pill{display:inline-block;font-size:12px;background:#FFE4D9;color:#8E2A0B;border-radius:6px;padding:2px 7px;margin:1px 0}.ko{color:#8E2A0B;font-weight:600}.scen{color:#15171C;font-style:italic;margin-top:4px}.mails{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,520px),1fr));gap:16px;margin-top:16px}.mail{background:#fff;border:1px solid #DCD8CF;border-radius:14px;overflow:hidden}.mh{padding:12px 16px;border-bottom:1px solid #DCD8CF;font-size:14px}.mb{padding:16px}h2{font-size:22px;margin:36px 0 0}`;
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Qui recevrait quoi · ${esc(cfg.marque)}</title>`
    + `<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Sora:wght@400;600;800&family=JetBrains+Mono:wght@500&display=swap"><style>${css}</style></head><body><div class="wrap">`
    + `<p class="eyebrow">Aperçu · aucun email envoyé · ${esc(frDateY(T))}</p><h1>Qui recevrait quoi ce matin</h1>`
    + `<p class="muted">${res.decisions.length} commandes analysées · ${nbClient} email(s) client · 1 récapitulatif interne (${res.digest.nb_alertes} alerte(s))${res.premierPassage ? ' · premier passage : aucune notification client' : ''}</p>`
    + `<div class="box"><table><tr><th>Commande</th><th>Statut ERP</th><th>Annoncée</th><th>Email client</th><th>Alertes équipe</th><th>Pourquoi</th></tr>${lignes}</table></div>`
    + `<h2>Emails clients</h2><div class="mails">${emails || '<p class="muted">Aucun email client.</p>'}</div>`
    + `<h2>Récapitulatif interne</h2><article class="mail" style="margin-top:16px"><div class="mh"><span class="muted">Objet</span> <b>${esc(res.digest.sujet)}</b></div><div class="mb">${res.digest.html}</div></article>`
    + `</div></body></html>`;
}

